        ,CAST(pc.START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(pc.END_DATE AS DATE) AS FACT_DATE_END
        ,dm.calendar_year_month AS CALENDAR_YEAR_MONTH
        ,pc.CONTRACT_TYPE
        ,CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
        ,pc.DIVISION
        ,pc.DOMAIN
        ,pc.SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_month') }} dm
        ON pc.START_DATE <= dm.last_day_of_month 
		AND (pc.END_DATE > dm.last_day_of_month OR pc.END_DATE IS NULL)
		AND YEAR(dm.last_day_of_month) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END = 'Consulting'
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        )
    ORDER BY PLACEMENT_HKEY, CALENDAR_YEAR_MONTH
)
, TOTAL_STARTING_HEADCOUNT AS
(
	-- Total starting headcount base set
    SELECT DISTINCT
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(END_DATE AS DATE) AS FACT_DATE_END
        ,dm.calendar_year_month AS CALENDAR_YEAR_MONTH
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_month') }} dm
        ON pc.START_DATE < dm.first_day_of_month 
        AND (pc.END_DATE >= dm.first_day_of_month OR pc.END_DATE IS NULL)
        AND YEAR(dm.first_day_of_month) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire')
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        )
    ORDER BY PLACEMENT_HKEY, CALENDAR_YEAR_MONTH
)
, TOTAL_ENDING_HEADCOUNT AS
(
	-- Total ending headcount base set
    SELECT DISTINCT
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(END_DATE AS DATE) AS FACT_DATE_END
        ,dm.calendar_year_month AS CALENDAR_YEAR_MONTH
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_month') }} dm
        ON pc.START_DATE <= dm.last_day_of_month 
		AND (pc.END_DATE > dm.last_day_of_month OR pc.END_DATE IS NULL)
		AND YEAR(dm.last_day_of_month) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire')
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        )
    ORDER BY PLACEMENT_HKEY, CALENDAR_YEAR_MONTH
)
, FACT_DATE_CTE AS
(
	-- Fact date base set
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        CALENDAR_YEAR_MONTH, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONTRACT_STARTING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        CALENDAR_YEAR_MONTH, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONTRACT_ENDING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        CALENDAR_YEAR_MONTH, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONSULTING_STARTING_HEADCOUNT
    UNION
    SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        CALENDAR_YEAR_MONTH, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONSULTING_ENDING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        CALENDAR_YEAR_MONTH, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM TOTAL_STARTING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        CALENDAR_YEAR_MONTH, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM TOTAL_ENDING_HEADCOUNT
    ORDER BY PLACEMENT_HKEY, CALENDAR_YEAR_MONTH
)
SELECT 
      FD.PLACEMENT_HKEY
    -- , FD.AIRBYTE_DATE
    -- , FD.FACT_DATE_START
    -- , FD.FACT_DATE_END
    ,FD.CALENDAR_YEAR_MONTH
    , CAST(SUM(CASE WHEN CONTRACT_STARTING_HEADCOUNT.CALENDAR_YEAR_MONTH IS NOT NULL THEN
					CASE WHEN CONTRACT_STARTING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONTRACT_STARTING_HEADCOUNT
	, CAST(SUM(CASE WHEN CONTRACT_ENDING_HEADCOUNT.CALENDAR_YEAR_MONTH IS NOT NULL THEN
					CASE WHEN CONTRACT_ENDING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONTRACT_ENDING_HEADCOUNT
	, CAST(SUM(CASE WHEN CONSULTING_STARTING_HEADCOUNT.CALENDAR_YEAR_MONTH IS NOT NULL THEN
					CASE WHEN CONSULTING_STARTING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONSULTING_STARTING_HEADCOUNT
    , CAST(SUM(CASE WHEN CONSULTING_ENDING_HEADCOUNT.CALENDAR_YEAR_MONTH IS NOT NULL THEN
					CASE WHEN CONSULTING_ENDING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONSULTING_ENDING_HEADCOUNT
	, CAST(SUM(CASE WHEN TOTAL_STARTING_HEADCOUNT.CALENDAR_YEAR_MONTH IS NOT NULL THEN
					CASE WHEN TOTAL_STARTING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS TOTAL_STARTING_HEADCOUNT
	, CAST(SUM(CASE WHEN TOTAL_ENDING_HEADCOUNT.CALENDAR_YEAR_MONTH IS NOT NULL THEN
					CASE WHEN TOTAL_ENDING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS TOTAL_ENDING_HEADCOUNT
    , FD.RECORD_TYPE
    , FD.DIVISION
    , FD.DOMAIN
    , FD.SEGMENT
FROM FACT_DATE_CTE FD
LEFT JOIN CONTRACT_STARTING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONTRACT_STARTING_HEADCOUNT.PLACEMENT_HKEY AND FD.CALENDAR_YEAR_MONTH = CONTRACT_STARTING_HEADCOUNT.CALENDAR_YEAR_MONTH
LEFT JOIN CONTRACT_ENDING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONTRACT_ENDING_HEADCOUNT.PLACEMENT_HKEY AND FD.CALENDAR_YEAR_MONTH = CONTRACT_ENDING_HEADCOUNT.CALENDAR_YEAR_MONTH
LEFT JOIN CONSULTING_STARTING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONSULTING_STARTING_HEADCOUNT.PLACEMENT_HKEY AND FD.CALENDAR_YEAR_MONTH = CONSULTING_STARTING_HEADCOUNT.CALENDAR_YEAR_MONTH
LEFT JOIN CONSULTING_ENDING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONSULTING_ENDING_HEADCOUNT.PLACEMENT_HKEY AND FD.CALENDAR_YEAR_MONTH = CONSULTING_ENDING_HEADCOUNT.CALENDAR_YEAR_MONTH
LEFT JOIN TOTAL_STARTING_HEADCOUNT
ON FD.PLACEMENT_HKEY = TOTAL_STARTING_HEADCOUNT.PLACEMENT_HKEY AND FD.CALENDAR_YEAR_MONTH = TOTAL_STARTING_HEADCOUNT.CALENDAR_YEAR_MONTH
LEFT JOIN TOTAL_ENDING_HEADCOUNT
ON FD.PLACEMENT_HKEY = TOTAL_ENDING_HEADCOUNT.PLACEMENT_HKEY AND FD.CALENDAR_YEAR_MONTH = TOTAL_ENDING_HEADCOUNT.CALENDAR_YEAR_MONTH
GROUP BY
     FD.PLACEMENT_HKEY
    -- , FD.AIRBYTE_DATE
    -- , FD.FACT_DATE_START
    -- , FD.FACT_DATE_END
     ,FD.CALENDAR_YEAR_MONTH
    , FD.RECORD_TYPE
    , FD.DIVISION
    , FD.DOMAIN
    , FD.SEGMENT